    target = data['target']
    faults = data['faults']

    n, m = len(A), len(A[0])
    valid_rows = []

    # For each row, check if it can be consistent with some x
    # We'll use rational_affine to solve each row independently
    for i in range(n):
        # Skip rows that are all zero in A, unless y[i] is zero
        if all(a == 0 for a in A[i]):
            if y[i] != 0:
                return {"status": "inconsistent"}
            continue

        # Try to solve A[i] · x = y[i]
        try:
            sol, null_basis = rational_affine([A[i]], [y[i]], 1)
            if sol is None:
                return {"status": "inconsistent"}
            x_sol = sol
            # Check if this row is consistent with some x
            valid_rows.append((i, x_sol))
        except:
            return {"status": "inconsistent"}

    # If no valid rows, inconsistent
    if not valid_rows:
        return {"status": "inconsistent"}

    # Build feasible x from consistent rows
    # We need to find all x such that at most faults rows have A[i]·x ≠ y[i]
    # Instead, we use the fact that if multiple x satisfy constraints, target·x may vary

    # Try to find a feasible x with at most faults errors
    # Use rational_affine to solve each row and collect solutions
    all_x = []
    for i in range(n):
        if all(a == 0 for a in A[i]):
            if y[i] != 0:
                return {"status": "inconsistent"}
            continue
        try:
            sol, null_basis = rational_affine([A[i]], [y[i]], 1)
            if sol is None:
                return {"status": "inconsistent"}
            x_sol = sol
            all_x.append((i, x_sol))
        except:
            return {"status": "inconsistent"}

    # If we have no consistent rows, inconsistent
    if not all_x:
        return {"status": "inconsistent"}

    # Check if all feasible x give same target·x
    # We only need to check a few representative x
    # Use the fact that null space vectors can generate other solutions

    # For each row, we have a solution x_i
    # The general solution is x_i + null_space_vector
    # We'll generate a few candidate x values and compute target·x

    # If we have only one row, just use that
    if len(all_x) == 1:
        x = all_x[0][1]
        val = sum(target[j] * x[j] for j in range(len(x)))
        return {"status": "determined", "value": str(val)}

    # For multiple rows, check if target·x is same across feasible solutions
    # We'll take one solution from each row and check if target·x is same
    # If not, return ambiguous

    # Use only one solution per row
    x_list = [x for _, x in all_x]

    # Compute target·x for each
    values = []
    for x in x_list:
        val = sum(target[j] * x[j] for j in range(len(x)))
        values.append(val)

    # If all values are equal, determined
    if all(abs(v - values[0]) == 0 for v in values):
        return {"status": "determined", "value": str(values[0])}

    # Otherwise, ambiguous
